// Aggregate KPIs from CRM data
const leads = $input.all();

const today = new Date().toISOString().split('T')[0];

// Count by status
const statusCounts = {};
const regionCounts = {};
const channelCounts = {};
const sourceCounts = {};

leads.forEach(lead => {
  const s = lead.json.status;
  const r = lead.json.region;
  const c = lead.json.channel;
  const src = lead.json.source;

  statusCounts[s] = (statusCounts[s] || 0) + 1;
  regionCounts[r] = (regionCounts[r] || 0) + 1;
  channelCounts[c] = (channelCounts[c] || 0) + 1;
  sourceCounts[src] = (sourceCounts[src] || 0) + 1;
});

const kpis = [
  { metric: 'Leads', value: leads.length, region: 'Kingdom-wide', date: today, channel: 'All', source: 'All' },
  { metric: 'MQLs', value: (statusCounts['Qualified'] || 0) + (statusCounts['Consultation Booked'] || 0), region: 'Kingdom-wide', date: today, channel: 'All', source: 'All' },
  { metric: 'SQLs', value: statusCounts['Consultation Booked'] || 0, region: 'Kingdom-wide', date: today, channel: 'All', source: 'All' },
  { metric: 'Applications', value: statusCounts['Applied'] || 0, region: 'Kingdom-wide', date: today, channel: 'All', source: 'All' },
  { metric: 'Enrollments', value: statusCounts['Enrolled'] || 0, region: 'Kingdom-wide', date: today, channel: 'All', source: 'All' }
];

// Add regional breakdown
Object.entries(regionCounts).forEach(([region, count]) => {
  kpis.push({ metric: 'Leads', value: count, region, date: today, channel: 'All', source: 'All' });
});

// Add channel breakdown
Object.entries(channelCounts).forEach(([channel, count]) => {
  kpis.push({ metric: 'Leads', value: count, region: 'Kingdom-wide', date: today, channel, source: 'All' });
});

// Add source breakdown (top 5)
Object.entries(sourceCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .forEach(([source, count]) => {
    kpis.push({ metric: 'Leads', value: count, region: 'Kingdom-wide', date: today, channel: 'All', source });
  });

return kpis.map(kpi => ({ json: kpi }));
